"""Run serial CPU workers and render an offline report; no production changes."""
import argparse
import hashlib
import importlib.metadata
import json
import os
from pathlib import Path
import platform
import subprocess
import sys
import time
import traceback

# Keep source directories free of generated bytecode during normal CLI use.
sys.dont_write_bytecode = True
from paths import CACHE, LOGS, RESULTS, ROOT, SCRIPTS, STUDY, ensure_outputs


def clean(value):
    """Strict JSON: missing/nonfinite measurements are null, never NaN tokens."""
    import numpy as np
    if isinstance(value, dict):
        return {str(k): clean(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [clean(x) for x in value]
    if isinstance(value, np.ndarray):
        return clean(value.tolist())
    if isinstance(value, (float, np.floating)):
        return float(value) if np.isfinite(value) else None
    if isinstance(value, np.integer):
        return int(value)
    return value


def save(path, data):
    path.write_text(json.dumps(clean(data), indent=2, allow_nan=False), encoding="utf-8")


def leaves(value):
    import numpy as np
    if isinstance(value, (tuple, list)):
        return [x for item in value for x in leaves(item)]
    return [np.asarray(value)]


def compare(value, reference, row):
    import numpy as np
    a, b = leaves(value), leaves(reference)
    if row["group"].startswith("projection") or row["group"] == "prepared_projection":
        # Coordinate agreement is not required for nonunique closest points.
        params = a[1]
        domain = bool(np.all(np.isfinite(params)) and np.all(params >= -1e-10) and np.all(params <= 1+1e-10))
        a, b = a[:1], b[:1]
    else:
        domain = True
    atol, rtol = (2e-4, 3e-5) if row["group"] in ("sensitivity", "sensitivity_projection") else (3e-6, 3e-6) if row["group"] in ("length", "map", "map_query") else (2e-9, 2e-8) if row["group"].startswith("projection") or row["group"] == "prepared_projection" else (2e-9, 2e-9)
    if len(a) != len(b) or any(x.shape != y.shape for x, y in zip(a, b)):
        return dict(passed=False, reason="Output structure/shape differs", shapes=[x.shape for x in a], reference_shapes=[x.shape for x in b], atol=atol, rtol=rtol)
    max_abs, max_scaled, nonfinite, passed = 0., 0., 0, domain
    for x, y in zip(a, b):
        finite = np.isfinite(x) & np.isfinite(y)
        nonfinite += int(np.size(x)-np.count_nonzero(finite))
        if np.any(finite):
            error = np.abs(x[finite]-y[finite])
            max_abs = max(max_abs, float(np.max(error)))
            max_scaled = max(max_scaled, float(np.max(error/(atol+rtol*np.abs(y[finite])))))
        if row["group"] == "degenerate":
            passed &= bool(np.array_equal(np.isnan(x), np.isnan(y)) and np.array_equal(np.isinf(x), np.isinf(y)))
        else:
            passed &= bool(np.all(finite))
    return dict(passed=bool(passed and max_scaled <= 1), max_abs=max_abs, max_scaled=max_scaled, nonfinite=nonfinite, domain=domain, atol=atol, rtol=rtol)


def metadata():
    packages = {}
    for name in ("nurbspy", "numpy", "scipy", "numba", "jax", "jaxlib", "equinox", "diffrax", "quadax", "optimistix", "matplotlib"):
        try:
            packages[name] = importlib.metadata.version(name)
        except importlib.metadata.PackageNotFoundError:
            packages[name] = None
    source = {p.relative_to(ROOT).as_posix(): hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((ROOT/"src/nurbspy").rglob("*.py"))}
    study = {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(SCRIPTS.glob("*.py"))}
    def git(*args):
        return subprocess.check_output(["git", *args], cwd=ROOT, text=True).strip()
    return dict(utc=time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), python=sys.version, executable=sys.executable, platform=platform.platform(), processor=platform.processor(), logical_cpus=os.cpu_count(), packages=packages, commit=git("rev-parse", "HEAD"), dirty=git("status", "--short"), source_sha256=source, study_sha256=study)


def worker(args):
    # Import after the parent sets JIT/thread/cache variables.
    import numpy as np
    from workloads import registry, make
    import nurbspy
    assert Path(nurbspy.__file__).resolve().is_relative_to(ROOT/"src"), nurbspy.__file__
    context = dict(source=nurbspy.__file__, thread_environment={k: os.environ.get(k) for k in ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS")})
    if args.worker == "jax":
        import jax
        jax.config.update("jax_enable_x64", True)
        jax.config.update("jax_enable_compilation_cache", False)
        sync = jax.block_until_ready
        # Runtime initialization is outside per-workload compiler measurements.
        sync(jax.numpy.ones(1)+1)
        context.update(device=[str(x) for x in jax.devices()], x64=bool(jax.config.jax_enable_x64), persistent_cache=bool(jax.config.jax_enable_compilation_cache))
        assert jax.default_backend() == "cpu" and context["x64"]
    else:
        sync = lambda x: x
        import nurbspy.numpy as numpy_backend
        accelerated = hasattr(numpy_backend.compute_basis_polynomials, "py_func")
        assert accelerated == (args.worker == "numba"), "Requested NumPy/Numba mode was not activated"
        context["numba_acceleration"] = accelerated
    records, arrays = [], {}
    out = RESULTS
    if args.select and (out/f"{args.worker}.json").exists():
        records = json.loads((out/f"{args.worker}.json").read_text())["records"]
        with np.load(out/f"{args.worker}.npz") as previous:
            arrays = {k: previous[k] for k in previous.files}
    selected = [r for r in registry() if (not args.select or args.select in r["id"]) and (args.worker == "jax" or not r["only_jax"])]
    for index, row in enumerate(selected):
        record = {**row, "profile": args.worker}
        key = row["id"].replace(".", "_")
        print(f"[{args.worker} {index+1}/{len(selected)}] {row['id']}", flush=True)
        try:
            if args.worker == "numba" and row["group"] == "basis" and row["op"] == "d4":
                # The former recursive implementation corrupted native memory
                # above degree. Keep this regression probe process-isolated.
                probe = subprocess.run([sys.executable, str(Path(__file__).resolve()), "--probe", row["id"], "--repeats", str(args.repeats)], capture_output=True, text=True, timeout=60)
                record["probe_returncode"] = probe.returncode
                record["probe_output"] = probe.stdout+probe.stderr
                if probe.returncode:
                    raise RuntimeError(f"Isolated above-degree basis probe exited {probe.returncode}; see raw record")
                payload = json.loads(next(line[7:] for line in probe.stdout.splitlines() if line.startswith("RESULT:")))
                value = [np.asarray(x) for x in payload.pop("value")]
                reference = [np.asarray(x) for x in payload.pop("reference_value")]
                record.update(payload, status="ok", timing_mode="isolated Numba call", shapes=[x.shape for x in value])
                record["reference"] = compare(value, reference, row)
                record["partition_error"] = float(np.max(np.abs(value[0].sum(axis=0))))
                record["notes"] = "Above-degree request remains process-isolated as a regression precaution after fixing the negative-degree recursion; first call includes loading shared compiled helpers."
                for i, x in enumerate(value):
                    arrays[f"{key}__out_{i}"] = x
                for i, x in enumerate(reference):
                    arrays[f"{key}__ref_{i}"] = x
                records = [r for r in records if r["id"] != row["id"]]+[record]
                save(out/f"{args.worker}.json", dict(profile=args.worker, context=context, records=records))
                np.savez_compressed(out/f"{args.worker}.npz", **arrays)
                continue
            start = time.perf_counter()
            function, inputs, reference, notes = make(row, args.worker)
            sync(inputs)
            record["setup_s"] = time.perf_counter()-start
            record["notes"] = notes
            if args.worker == "jax" and not row["host"]:
                start = time.perf_counter()
                lowered = jax.jit(function).lower(*inputs)
                record["lower_s"] = time.perf_counter()-start
                start = time.perf_counter()
                execute = lowered.compile()
                record["compile_s"] = time.perf_counter()-start
                record["timing_mode"] = "explicit JIT"
            else:
                execute = function
                record["timing_mode"] = "host first-call" if row["host"] else "Python/Numba call"
            start = time.perf_counter()
            value = sync(execute(*inputs))
            record["first_s"] = time.perf_counter()-start
            samples = []
            for _ in range(args.repeats):
                start = time.perf_counter()
                value = sync(execute(*inputs))
                samples.append(time.perf_counter()-start)
            record["warm_samples_s"] = samples
            record["warm_median_s"] = float(np.median(samples))
            record["cold_s"] = sum(record.get(k, 0) for k in ("lower_s", "compile_s", "first_s"))
            record["status"] = "ok"
            record["shapes"] = [x.shape for x in leaves(value)]
            for i, x in enumerate(leaves(value)):
                arrays[f"{key}__out_{i}"] = x
            if reference is not None:
                record["reference"] = compare(value, reference, row)
                for i, x in enumerate(leaves(reference)):
                    arrays[f"{key}__ref_{i}"] = x
            if row["group"] == "basis":
                x = leaves(value)[0]
                expected = 1 if row["op"] == "value" else 0
                record["partition_error"] = float(np.max(np.abs(x.sum(axis=0)-expected)))
        except Exception as error:
            record.update(status="error", error=f"{type(error).__name__}: {error}", traceback=traceback.format_exc())
            print(record["error"], flush=True)
        records = [r for r in records if r["id"] != row["id"]] + [record]
        save(out/f"{args.worker}.json", dict(profile=args.worker, context=context, records=records))
        np.savez_compressed(out/f"{args.worker}.npz", **arrays)
        if args.worker == "jax":
            jax.clear_caches()
    return 0


def run_worker(command, environment, log_path):
    """Show worker progress while retaining its stdout/stderr under outputs/."""
    log_path.parent.mkdir(parents=True, exist_ok=True)
    with log_path.open("w", encoding="utf-8") as log:
        with subprocess.Popen(
            command, cwd=ROOT, env=environment, stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT, text=True, encoding="utf-8", errors="replace",
        ) as process:
            for line in process.stdout:
                print(line, end="", flush=True)
                log.write(line)
                log.flush()
            return process.wait()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--worker", choices=["numpy", "numba", "jax"])
    parser.add_argument("--probe", help=argparse.SUPPRESS)
    parser.add_argument("--profiles", nargs="+", default=["numpy", "numba", "jax"], choices=["numpy", "numba", "jax"])
    parser.add_argument("--repeats", type=int, default=7)
    parser.add_argument("--select", default="", help="Substring of workload ID, for diagnosis")
    parser.add_argument("--report-only", action="store_true")
    args = parser.parse_args()
    if args.probe:
        from workloads import registry, make
        import numpy as np
        row = next(r for r in registry() if r["id"] == args.probe)
        function, inputs, reference, _ = make(row, "numba")
        start = time.perf_counter()
        value = function(*inputs)
        first = time.perf_counter()-start
        samples = []
        for _ in range(args.repeats):
            start = time.perf_counter()
            value = function(*inputs)
            samples.append(time.perf_counter()-start)
        print("RESULT:"+json.dumps(clean(dict(value=leaves(value), reference_value=leaves(reference), first_s=first, cold_s=first, warm_median_s=float(np.median(samples)), warm_samples_s=samples)), allow_nan=False))
        return 0
    ensure_outputs()
    if args.worker:
        return worker(args)
    if not args.report_only:
        if not args.select or not (RESULTS/"environment.json").exists():
            save(RESULTS/"environment.json", {**metadata(), "profiles": args.profiles})
        else:
            save(RESULTS/f"rerun-{time.time_ns()}.json", dict(selection=args.select, profiles=args.profiles, environment=metadata()))
        for profile in args.profiles:
            if not args.select:
                # A worker that dies before its first write must not leave the
                # previous run looking like newly measured complete results.
                for suffix in (".json", ".npz"):
                    (RESULTS/(profile+suffix)).unlink(missing_ok=True)
            env = dict(os.environ, MPLBACKEND="Agg", OMP_NUM_THREADS="1", OPENBLAS_NUM_THREADS="1", MKL_NUM_THREADS="1", NUMBA_DISABLE_JIT="1" if profile == "numpy" else "0", JAX_ENABLE_X64="True", JAX_PLATFORMS="cpu", JAX_ENABLE_COMPILATION_CACHE="false", PYTHONDONTWRITEBYTECODE="1", PYTHONIOENCODING="utf-8")
            # Separate fresh disk cache for Numba, never touch the user's cache.
            import uuid
            # Keep cache paths short enough for Windows' legacy MAX_PATH.
            cache = CACHE/("nb-"+uuid.uuid4().hex[:8])
            cache.mkdir()
            env["NUMBA_CACHE_DIR"] = str(cache)
            command = [sys.executable, str(Path(__file__).resolve()), "--worker", profile, "--repeats", str(args.repeats), "--select", args.select]
            log_path = LOGS/f"{profile}-{time.time_ns()}.log"
            returncode = run_worker(command, env, log_path)
            if returncode:
                print(f"Worker {profile} exited {returncode}; retaining partial results. Log: {log_path}", flush=True)
            # Only remove the exact cache directory created for this worker.
            # Verify its resolved parent/name before any recursive operation.
            import shutil
            resolved = cache.resolve()
            if resolved.parent != CACHE.resolve() or not resolved.name.startswith("nb-"):
                raise RuntimeError(f"Unexpected cache path: {resolved}")
            shutil.rmtree(resolved)
    from report import render
    render()
    print(STUDY/"report.html")


if __name__ == "__main__":
    raise SystemExit(main())
